@Test
@Transactional
void 덮어쓰기() {
    Member saved = memberRepository.save(new Member("원래이름", 30));
    saved.setTeam(teamRepository.save(new Team("teamA")));
    em.flush(); em.clear();

    Member partial = new Member();
    partial.setId(saved.getId());
    partial.setUsername("새이름");          // age 와 team 은 안 넣었다

    memberRepository.save(partial);
    em.flush(); em.clear();

    Member after = memberRepository.findById(saved.getId()).orElseThrow();
    System.out.println("이름: " + after.getUsername());
    System.out.println("나이: " + after.getAge());
    System.out.println("팀:   " + after.getTeam());
}

