-- 반환값을 안 받으면

@Test
@Transactional
void 반환값() {
    Member saved = memberRepository.save(new Member("m3", 10));
    em.flush(); em.clear();

    Member detached = new Member("고침", 20);
    detached.setId(saved.getId());

    memberRepository.save(detached);        // 반환을 버렸다
    System.out.println("넘긴 것 관리 중? " + em.contains(detached));

    Member returned = memberRepository.save(detached);
    System.out.println("받은 것 관리 중? " + em.contains(returned));
    System.out.println("같은 객체?      " + (detached == returned));
}

