-- 만 건이면

@Test
@Transactional
void 만_건() {
    long t1 = System.nanoTime();
    for (int i = 0; i < 10000; i++)
        memberRepository.save(new Member("m" + i, 10));
    em.flush(); em.clear();
    System.out.printf("자동 id: %d ms%n", (System.nanoTime()-t1)/1_000_000);

    long t2 = System.nanoTime();
    for (int i = 0; i < 10000; i++)
        itemRepository.save(new Item("I-" + i, "품목"));
    em.flush(); em.clear();
    System.out.printf("직접 id: %d ms%n", (System.nanoTime()-t2)/1_000_000);
}

